function makeMarker(){const q=qrcode(1,'L');q.addData('1','Numeric');q.make();const n=q.getModuleCount(),inner=document.createElement('canvas');inner.width=inner.height=256;const c=inner.getContext('2d');c.fillStyle='white';c.fillRect(0,0,256,256);c.fillStyle='black';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(q.isDark(y,x)){let a=Math.round((x+4)*256/(n+8)),b=Math.round((y+4)*256/(n+8));c.fillRect(a,b,Math.round((x+5)*256/(n+8))-a,Math.round((y+5)*256/(n+8))-b)}const card=document.createElement('canvas');card.width=card.height=640;const d=card.getContext('2d');d.fillStyle='white';d.fillRect(0,0,640,640);d.fillStyle='black';d.fillRect(64,64,512,512);d.drawImage(inner,192,192,256,256);let pattern='';for(let r=0;r<4;r++){const tiny=document.createElement('canvas');tiny.width=tiny.height=16;const t=tiny.getContext('2d');t.translate(8,8);t.rotate(-r*Math.PI/2);t.drawImage(inner,-8,-8,16,16);const p=t.getImageData(0,0,16,16).data;for(let ch=2;ch>=0;ch--)for(let y=0;y<16;y++){for(let x=0;x<16;x++)pattern+=String(p[(y*16+x)*4+ch]).padStart(3,' ')+' ';pattern+='\n'}pattern+='\n'}return{card,pattern}}
